INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62981575', 62981575, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Survei dan Pemetaan Pertanahan dan Ruang', 'Tenaga Pendukung pada Kegiatan Pelaksanaan Kompilasi dan Integrasi IGT Pertanahan dan Ruang dalam mendukung Kebijakan Satu Peta', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 68400000, 'December 2025', 'APBN - PNBP (D)', 1, 1, '12 Bulan', 'Kegiatan ini dilaksanakan secara kontraktual melalui metode pengadaan langsung. Ruang lingkup pekerjaan Tenaga Pendukung Kompilasi kegiatan Kompilasi IGT Pertanahan dan Ruang adalah memberikan dukungan teknis maupun administratif dalam pengelolaan IGT Pertanahan dan Ruang untuk integrasi data geospasial sesuai dengan standar Kebijakan Satu Peta dan Satu Data Indonesia. Adapun keluaran yang dihasilkan berupa: Dokumen rancangan kegiatan pengelolaan IGT Pertanahan dan Ruang; Pendampingan pengelolaan IGT Pertanahan dan Ruang dalam bentuk IGT Pertanahan dan Ruang terkompilasi dan terintegrasi baik secara internal Kementerian ATR/BPN dan nasional (Kebijakan Satu Peta dan Satu Data Indonesia); serta Dokumen hasil pendampingan, monitoring dan evaluasi pengelolaan IGT Pertanahan dan Ruang yang disampaikan setiap bulan sebagai evidence kemajuan pekerjaan.', 'Kegiatan ini dilaksanakan secara kontraktual melalui metode pengadaan langsung. Ruang lingkup pekerjaan Tenaga Pendukung Kompilasi kegiatan Kompilasi IGT Pertanahan dan Ruang adalah memberikan dukungan teknis maupun administratif dalam pengelolaan IGT Pertanahan dan Ruang untuk integrasi data geospasial sesuai dengan standar Kebijakan Satu Peta dan Satu Data Indonesia. Adapun keluaran yang dihasilkan berupa: Dokumen rancangan kegiatan pengelolaan IGT Pertanahan dan Ruang; Pendampingan pengelolaan IGT Pertanahan dan Ruang dalam bentuk IGT Pertanahan dan Ruang terkompilasi dan terintegrasi baik secara internal Kementerian ATR/BPN dan nasional (Kebijakan Satu Peta dan Satu Data Indonesia); serta Dokumen hasil pendampingan, monitoring dan evaluasi pengelolaan IGT Pertanahan dan Ruang yang disampaikan setiap bulan sebagai evidence kemajuan pekerjaan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 360044);
