INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62243324', 62243324, 'analyze_legacy', 'Kab. Subang', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Pelaksana Siaran 2', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Barat, Subang (Kab.)', 36000000, 'December 2025', 'APBD', 1, 1, '1 x 12', '(1.) Menyampaikan informasi publik, edukasi, dan hiburan kepada pendengar Radio Benpas secara komunikatif, akurat, dan bertanggung jawab; (2.) Membawakan dan memandu program siaran radio sebagai representasi suara dan citra Radio Benpas; (3.) Melakukan interaksi langsung dengan pendengar melalui saluran komunikasi yang tersedia guna meningkatkan partisipasi dan kedekatan dengan masyarakat; (4.) Membangun, menjaga, dan memperkuat citra positif Radio Benpas sebagai media informasi publik milik Pemerintah Daerah; (5.) Membacakan berita, iklan layanan masyarakat, naskah siaran, pengumuman resmi, serta informasi cuaca sesuai dengan standar penyiaran; (6.) Melakukan pemutaran lagu dan materi audio lainnya sesuai dengan format dan kebijakan program siaran Radio Benpas; (7.) Melakukan wawancara dengan narasumber atau tamu siaran untuk mendukung penyampaian informasi yang aktual, edukatif, dan relevan; (8.) Bertindak sebagai moderator dalam program diskusi, dialog interaktif, dan talk show radio; (9.) Menyampaikan berita hasil liputan reporter di lapangan secara jelas, objektif, dan sesuai kaidah jurnalistik; (10.) Menjaga dan membangun hubungan kerja yang baik dengan jaringan sumber berita, narasumber, dan mitra siaran; (11.) Melaksanakan wawancara serta interaksi dengan narasumber secara profesional sesuai etika penyiaran; (12.) Mendukung kelancaran operasional siaran, termasuk koordinasi dengan tim produksi, teknisi, dan redaksi; (13.) Melaksanakan tugas lain yang berkaitan dengan penyiaran radio sesuai kebutuhan dan arahan pimpinan UPTD Benpas Diskominfo Kabupaten Subang.', '(1) Pendidikan minimal SMA/SMK/D3; (2) Pengalaman Pekerjaan sejenis minimal 1 tahun', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 362109);
