INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62245055', 62245055, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Ketentuan/Perencanaan Penataan Ruang  Senior Assistant Professional Staff - 02', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 75075000, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Pekerjaan yang dilakukan meliputi: 1. Pengumpulan data primer dan sekunder; 2. Pengkajian atau analisis; 3. Merangkum hasil analisis dan perumusan; 4. Pembuatan usulan penataan kawasan dalam bentuk 3D maupun animasi; 5. Penyusunan skenario penataan kawasan dan dituangkan dalam bentuk indikasi program; 6. Penyusunan bahan paparan atau presentasi untuk setiap pembahasan laporan; 7. Penyusunan buku laporan beserta lampiran gambar dan peta; 8. Merangkum dan merumuskan hasil pembahasan setiap buku laporan serta menyempurnakan buku laporan tersebut; 9. Pelaksanaan rapat /diskusi; dan 10. Pembahasan dengan tim Suku Dinas Cipta Karya, Tata Ruang, dan Pertanahan Kota Administrasi Jakarta Pusat."', '"Pekerjaan Senior Assistant Professional Staff di bidang Arsitektur/Planologi/Perencanaan Wilayah Kota, meliputi: 1. Pendidikan Minimal S1 Arsitektur/Planologi/Perencanaan Wilayah Kota dari Universitas Negeri/ Swasta; 2. Pengalaman Kerja 0-3 tahun di bidang urban design, perencanaan wilayah perkotaan, penataan kawasan dan atau pekerjaan sejenis; 3. Memiliki ide dan gagasan tentang urban design, perencanaan wilayah perkotaan, penataan kawasan dan atau pekerjaan sejenis; 4. Menguasai Autocad, Arc GIS/Arc Map, Ms. Office (S1 Planologi/ Perencanaan Wilayah); 5. Menguasai Autocad, SketchUp, Ms. Office, memiliki kemampuan membuat animasi 3D/desain grafis/visualisasi (S1 Arsitektur); 6. Menguasai program lain yang menunjang pekerjaan (3ds Max, Adobe Photoshop, Illustrator, Coreldraw, Audesk Maya, Lumion, Blender, Sketch Up, Adobe Photoshop, ErMapper, SPSS, dll.) dan program lain yang menunjang pekerjaan; 7. Diutamakan memiliki Sertifikat Keahlian Tata lingkungan Ahi Perencanaan Wilayah dan Kota (SKA 502) bagi S1 Planologi Diutamakan memiliki memiliki Sertifikat Keahlian Arsitektur (SKA 101) bagi S1 Arsitektur; 8. Memiliki kemampuan pengetahuan, perencanaan dan perancangan tata ruang kota dan mampu melakukan analisis serta menyusun perencanaan perancangan kawasan (urban desain); 9. Melampirkan Portofolio selama bekerja (jika ada); 10. Mampu memperoleh dan mengumpulkan data kajian secara primer dan sekuder; 11. Mampu bekerja secara individual dan kelompok/tim, siap bekerja di bawah tekanan, mampu bekerja sesuai arahan; 12. Mampu memaparkan/mempresentasikan setiap tahapan hasil penataan kawasan ; 13. Memiliki Laptop sendiri dengan spesifikasi yang mendukung; 14. Memiliki kendaraan dan mampu mengemudikan kendaraan roda 2 dan/ atau roda 4 serta memiliki SIM A dan/ atau SIM C aktif (jika ada); 15. Memiliki NIB dan terdaftar dalam SIKAP/SPSE."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 362561);
