INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62246075', 62246075, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Pelaksanaan Pengawasan Pemanfaatan  Ruang Senior Assistant Professional Staff -   Pengawasan Pemanfaatan Ruang 01', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Pekerjaan yang dilakukan meliputi: 1. Melaksanakan pengawasan secara periodik terhadap pemanfaatan ruang baik pola maupun struktur ruang 2.Penyusunan data base hasil monitoring (pengawasan) atas pemanfaatan ruang; 3. Melaksanakan pengawasan secara periodik terhadap penyelenggaraan reklame yang berlokasi pada sarana dan prasarana yang dilakukan secara periodik 4.Penyusunan data base hasil monitoring (pengawasan) atas konstruksi menara telekomunikasi dan reklame yang berlokasi pada sarana dan prasarana; 5.Melaksanakan pengawasan terhadap pemenuhan kewajiban Surat Izin Penunjukan Penggunaan Tanah (SIPPT) / Izin Penunjukan Penggunaan Tanah (IPPT)/ Izin Prinsip Pemanfaatan Ruang (IPPR); 6.Melaksanakan penyusunan bahan pengenaan sanksi pelanggaran pemanfaatan ruang secara periodik. 7. Menyusun bahan evaluasi pemanfaatan prasarana kota meliputi jalan, tata air, ruang terbuka hijau, utilitas dan sarana kota. 8. Membantu pelaksanaan tugas tupoksi Seksi Pemanfaatan dan Pengendalian Ruang Suku Dinas Cipta Karya Tata Ruang dan Pertanahan Jakarta Pusat."', '"Pekerjaan Senior Assistant Professional Staff di bidang Planologi/Perencanaan Wilayah dan Kota/Arsitektur, meliputi: 1. Pendidikan Minimal S1 dari Universitas Negeri/ Swasta; 2. Pengalaman Kerja 0-3 tahun di bidang pemanfaatan dan pengendalian ruang; 3. Menguasai Autocad, Arc GIS/Arc Map, Arc GIS Pro, Ms. Office; 4. Menguasai program lain yang menunjang pekerjaan (3ds Max, Adobe Photoshop, Illustrator, Coreldraw, Audesk Maya, Lumion, Blender, Sketch Up, Adobe Photoshop, ErMapper, SPSS, dll.) dan program lain yang menunjang pekerjaan; 5. Diutamakan memiliki Sertifikat Keahlian Tata lingkungan Ahi Perencanaan Wilayah dan Kota (SKA 502) bagi S1 Perencanaan Wilayah; 6. Diutamakan memiliki memiliki Sertifikat Keahlian Arsitektur (SKA 101) bagi S1 Arsitektur; 7. Mampu mengumpulkan data primer dan sekunder untuki keperluan studi 8. Memiliki kemampuan pengetahuan, perencanaan dan perancangan tata ruang kota dan mampu melakukan analisis serta menyusun perencanaan perancangan kawasan (urban desain); 9. Melampirkan Portofolio selama bekerja (jika ada); 10.Mampu bekerja secara individual dan kelompok/tim, siap bekerja di bawah tekanan, mampu bekerja sesuai arahan; 11. Mampu memaparkan/mempresentasikan setiap tahapan kegiatan; 12. Memiliki Laptop sendiri dengan spesifikasi yang men-dukung; 13. Memiliki kendaraan sendiri dan mampu mengemudikan kendara-an roda 2 dan/ atau roda 4 serta memiliki SIM A dan/ atau SIM C aktif; 14. Memiliki Kartu Tanda Penduduk (KTP), Nomor Pokok Wajib Pajak (NPWP), Curriculum Vitae, Ijazah dan Transkrip Nilai; 15. Memiliki NIB dan akun LPSE."', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 363023);
