INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62247317', 62247317, 'analyze_legacy', 'Mahkamah Agung', 'central', 'PENGADILAN AGAMA CIBINONG', 'Pengadaan Jasa Konsultansi Layanan Bantuan Hukum (POSBAKUM)', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Barat, Bogor (Kab.)', 100000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1000 orang', 'Pengadaan Jasa Konsultansi Layanan Bantuan Hukum pada Pengadilan Agama Cibinong Tahun Anggaran 2026 dilaksanakan untuk mendukung pemenuhan hak masyarakat pencari keadilan, khususnya bagi pihak yang tidak mampu secara ekonomi, agar memperoleh akses keadilan yang setara dan berkeadilan. Layanan ini bertujuan memberikan informasi, konsultasi, dan bantuan hukum kepada para pihak yang berperkara, sehingga proses peradilan dapat berjalan secara efektif, tertib, dan sesuai dengan ketentuan peraturan perundang-undangan. Pengadaan jasa konsultansi ini mencakup penyediaan tenaga pemberi bantuan hukum yang memiliki kompetensi dan kualifikasi sesuai dengan standar yang ditetapkan, termasuk memiliki legalitas sebagai organisasi bantuan hukum atau tenaga profesional yang berpengalaman di bidang hukum. Pelaksanaan layanan bantuan hukum dilakukan sesuai dengan kebutuhan pelayanan di Pengadilan Agama Cibinong, dengan tetap memperhatikan prinsip profesionalitas, independensi, dan akuntabilitas dalam pemberian layanan kepada masyarakat.Proses pemilihan penyedia jasa direncanakan dilaksanakan sesuai dengan ketentuan pengadaan barang/jasa pemerintah yang berlaku dan disesuaikan dengan pagu anggaran dalam DIPA Tahun Anggaran 2026. Pembayaran dilakukan berdasarkan kontrak yang telah ditetapkan, dengan memperhatikan ketentuan yang berlaku. Seluruh rangkaian pengadaan dan pelaksanaan layanan bantuan hukum wajib mengedepankan prinsip efisien, efektif, transparan, dan akuntabel guna mendukung peningkatan kualitas pelayanan publik serta mewujudkan peradilan yang sederhana, cepat, dan berbiaya ringan di Pengadilan Agama Cibinong.', 'Penyedia jasa konsultansi Pos Bantuan Hukum memberikan layanan berupa: 1. Pemberian informasi, konsultasi, atau advis hukum; 2. Bantuan pembuatan dokumen hukum yang dibutuhkan; 3. Penyediaan informasi daftar Organisasi Bantuan Hukum sebagaimana dimaksud dalam Undang-undang Nomor 16 Tahun 2011 tentang Bantuan Hukum atau organisasi bantuan hukum atau advokat lainnya yang dapat memberikan bantuan hukum cuma-cuma.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 363178);
