INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62984021', 62984021, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Kertas HVS - Penilaian', 'Barang', 'E-Purchasing', 'Jawa Timur, Sidoarjo (Kab.)', 675000, 'January 2026', 'APBD', 1, 1, '10 Rim', 'Belanja Kertas HVS Ukuran F4 ini meliputi kegiatan pengadaan, penyediaan, dan pengiriman kertas HVS ukuran F4 yang akan digunakan untuk mendukung kelancaran kegiatan administrasi perkantoran, pelayanan publik, serta penyusunan dokumen resmi pada perangkat daerah. Penyedia bertanggung jawab menyediakan kertas HVS ukuran F4 yang memenuhi spesifikasi teknis yang dipersyaratkan, antara lain ukuran F4 (± 21,5 x 33 cm), gramatur sesuai kebutuhan (umumnya 70 gsm atau 80 gsm), warna putih cerah, permukaan halus, tidak mudah tembus tinta, serta kompatibel untuk penggunaan mesin fotokopi, printer inkjet, dan printer laser.', 'Spesifikasi Teknis Belanja Kertas HVS Ukuran F4 1. Nama Barang Kertas HVS Ukuran F4 2. Jenis Barang Alat Tulis Kantor (ATK) 3. Ukuran Ukuran kertas: F4 Dimensi: ± 21,5 cm x 33 cm 4. Bahan Bahan dasar: Pulp kayu berkualitas Bebas dari bahan berbahaya dan aman digunakan untuk keperluan administrasi perkantoran 5. Gramatur 70 gsm 6. Warna Putih cerah 7. Tingkat Keputihan (Brightness) Minimal 90% 8. Karakteristik Teknis Permukaan halus dan rata Tidak mudah tembus tinta Tidak mudah macet pada mesin Tidak mudah robek Cocok untuk penggunaan mesin fotokopi, printer inkjet, dan printer laser 9. Kemasan Dikemas dalam rim (500 lembar) Kemasan pabrik masih tersegel, rapi, dan tidak rusak Setiap kemasan dilengkapi identitas produk 10. Kondisi Barang Baru (bukan rekondisi) Tidak lembab, tidak cacat, dan tidak menguning 11. Standar Mutu Memenuhi standar mutu kertas HVS yang berlaku di Indonesia Disarankan memiliki sertifikasi ramah lingkungan (apabila tersedia) 12. Jumlah Sesuai dengan kebutuhan dan tercantum dalam kontrak atau surat pesanan 13. Tempat Pengiriman Sesuai lokasi yang ditetapkan oleh PPK/Pejabat Pengadaan 14. Jangka Waktu Pengiriman Maksimal sesuai ketentuan dalam kontrak/SP 15. Pemeriksaan dan Serah Terima Barang diperiksa oleh Pejabat Penerima Hasil Pekerjaan (PPHP)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 364738);
