INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62291953', 62291953, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Keperluan Rapat Koordinasi Pimpinan Untuk Kegiatan Operasional dan Pemeliharaan Kantor Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan Republik Indonesia Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 72388000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 Tahun', 'Pekerjaan ini mencakup pemenuhan kebutuhan pelaksanaan rapat koordinasi pimpinan yang diselenggarakan secara berkala selama jangka waktu satu tahun guna mendukung koordinasi, sinkronisasi, dan pengambilan keputusan pimpinan pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyarakatan. Ruang lingkup pekerjaan meliputi penyediaan kebutuhan pendukung rapat sesuai ketentuan yang berlaku, termasuk perlengkapan rapat, konsumsi, serta kebutuhan pendukung lainnya yang diperlukan selama pelaksanaan rapat. Kegiatan dilaksanakan secara berkelanjutan sesuai jadwal dan kebutuhan organisasi untuk menunjang kelancaran pelaksanaan tugas dan fungsi Inspektorat Jenderal.', 'Kebutuhan rapat koordinasi pimpinan dilaksanakan selama 1 tahun dan disesuaikan dengan frekuensi serta kebutuhan rapat yang ditetapkan. Spesifikasi pekerjaan meliputi penyediaan perlengkapan rapat yang layak dan siap digunakan, konsumsi rapat sesuai standar yang berlaku, serta kebutuhan pendukung rapat lainnya yang diperlukan untuk menunjang kelancaran pelaksanaan rapat. Seluruh kebutuhan rapat disediakan secara bertahap sesuai pelaksanaan kegiatan, dengan memperhatikan efisiensi, efektivitas, serta ketentuan administrasi yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 366090);
